const input = $json || {};
const headers = input.headers || {};
const body = input.body || {};

// Conserva el mismo secreto que ya usa el CRM/Vercel.
const EXPECTED_SECRET = 'eagles2026';
const receivedSecret = String(headers['x-eagles-secret'] || headers['X-Eagles-Secret'] || '');

if (!receivedSecret || receivedSecret !== EXPECTED_SECRET) {
  throw new Error('Solicitud no autorizada');
}

const request = body.copy_request || {};
const clean = (value) => String(value || '').trim();
const normalize = (value) =>
  clean(value).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

const channels = Array.isArray(request.channels) && request.channels.length
  ? request.channels.map(clean).filter(Boolean)
  : ['Facebook', 'Instagram'];

if (!clean(request.product_topic)) {
  throw new Error('Falta product_topic');
}

const categoryLabels = {
  social: 'redes sociales',
  taller: 'servicios del taller de transmisiones',
  course: 'curso o capacitación de transmisiones'
};

const facts = [
  clean(request.brief),
  clean(request.call_to_action) ? `CTA solicitado: ${clean(request.call_to_action)}` : '',
  clean(request.audience) ? `Audiencia: ${clean(request.audience)}` : '',
  clean(request.image_brief) ? `Brief visual: ${clean(request.image_brief)}` : ''
].filter(Boolean).join('\n');

const normalizedTopic = normalize(request.product_topic);
const normalizedObjective = normalize(request.objective);
const normalizedCampaign = normalize(
  request.campaign_code || body.campaign_code || body.copy_request?.campaign_code
);

const isWorkshopConvencionales =
  normalizedCampaign.includes('workshop_octubre') ||
  (normalizedTopic.includes('workshop') && normalizedTopic.includes('convencional'));

const isJF017 =
  normalizedCampaign.includes('jf017') ||
  normalizedTopic.includes('jf017') ||
  (normalizedTopic.includes('cvt') && normalizedTopic.includes('017'));

const isWhatsAppWarmup =
  channels.length === 1 &&
  channels[0].toLowerCase() === 'whatsapp' &&
  normalizedObjective.includes('calentamiento');

const hasSocialChannel = channels.some((channel) =>
  ['facebook', 'instagram', 'tiktok'].includes(channel.toLowerCase())
);

// ============================================================
// WORKSHOP OCTUBRE · NO CAMBIAR
// ============================================================
const WORKSHOP_GROUP_URL =
  'https://chat.whatsapp.com/Gu955o9muhZ2eJGOaRw0wS?s=cl&p=i&mlu=4&ilr=4';
const WORKSHOP_HOTMART_URL =
  'https://pay.hotmart.com/U107474945W?bid=1788557927997';

// ============================================================
// CURSO CVT JF017 · OCTUBRE
// ============================================================
const JF017_DEFAULT_CTA = '📲 Más información: 449 110 7766';
const jf017CTA = clean(request.call_to_action) || JF017_DEFAULT_CTA;

let structureRules = '';

// ---------- WORKSHOP ----------
if (isWorkshopConvencionales && isWhatsAppWarmup) {
  structureRules = `
ESTRUCTURA OBLIGATORIA PARA CALENTAMIENTO DE WORKSHOP EN WHATSAPP:
1. Abre con UNA sola línea cercana y energética. Puedes usar “⚙️ ¡CARNALITOS!” o una variante natural.
2. Da valor en UNA sola frase corta sobre un problema, aprendizaje o punto técnico de transmisiones convencionales.
3. Coloca inmediatamente este bloque, cada dato en su propia línea:
📅 2 y 3 de octubre
💻 Online en vivo vía Zoom
💲 17 USD
4. Cierra directamente con:
👉 Inscríbete aquí:
${WORKSHOP_HOTMART_URL}
5. NO uses el link del grupo de WhatsApp dentro del calentamiento.
6. Máximo aproximado: 70 palabras antes del enlace. Evita introducciones largas, repeticiones y relleno.`;
} else if (isWorkshopConvencionales && hasSocialChannel) {
  structureRules = `
ESTRUCTURA OBLIGATORIA PARA COPY DE REDES DE LA WORKSHOP:
1. Primera línea: gancho o pregunta basada en un problema real del técnico/taller.
2. Segundo párrafo: beneficio concreto de la Workshop en 1 o 2 frases.
3. Cierre con invitación clara a entrar al grupo.
4. Últimas dos líneas exactamente:
🔥 Únete al grupo y recibe toda la información para asegurar tu acceso:
👉 ${WORKSHOP_GROUP_URL}
5. NO pongas el link de Hotmart en el copy de captación para redes.
6. No satures con todos los datos del evento; el objetivo es llevarlos al grupo.`;
}

// ---------- CURSO CVT JF017 ----------
else if (isJF017 && isWhatsAppWarmup) {
  structureRules = `
ESTRUCTURA OBLIGATORIA PARA CALENTAMIENTO DEL CURSO CVT JF017 EN WHATSAPP:
1. Abre con UNA sola línea breve y llamativa. Puede ser una pregunta técnica, “⚙️ ¡CARNALITOS!” o una frase de identificación con el taller.
2. Habla de UN SOLO punto técnico por mensaje. Mantén la explicación en 1 o 2 frases cortas.
3. Si el brief no propone un tema técnico concreto, puedes usar SOLO uno de estos temas confirmados:
   - funcionamiento de la CVT JF017/JF017E;
   - poleas primaria/secundaria y uso de cadena;
   - cuerpo de válvulas y control de presión;
   - códigos P17F0 o P17F1;
   - códigos P0841, P0744, P0776, P0965, P0715 o P0720;
   - temperatura y deterioro del aceite;
   - TCM, actualización de software o revisión de componentes antes de condenar la transmisión.
4. Después del valor técnico coloca este bloque compacto:
📅 16 y 17 de octubre
💻 100% online
🕚 Vie 11:00 a.m.–5:00 p.m. | Sáb 11:00 a.m.–3:00 p.m. MX
💲 $2,997 MXN · Aparta con $1,500
5. Si encaja naturalmente, puedes mencionar en UNA sola línea: incluye grabaciones, manuales de apoyo y calibraciones de regalo.
6. Cierra con este CTA, respetándolo literalmente:
${jf017CTA}
7. Máximo aproximado: 85 palabras antes del CTA.
8. NO inventes link de pago ni link de grupo si no viene en CTA solicitado.`;
} else if (isJF017 && hasSocialChannel) {
  structureRules = `
ESTRUCTURA OBLIGATORIA PARA COPY DE REDES DEL CURSO CVT JF017:
1. Primera línea: gancho o pregunta sobre un dolor técnico real relacionado con CVT/JF017.
2. Segundo párrafo: beneficio concreto del curso en 1 o 2 frases.
3. Puedes mencionar máximo 2 datos del evento dentro del cuerpo; evita saturar.
4. Cierra con el CTA recibido. Si no se recibió CTA, usa exactamente:
${JF017_DEFAULT_CTA}
5. No inventes enlaces.
6. Mantén el copy corto, directo y listo para Facebook, Instagram o TikTok.`;
}

const systemPrompt = `Eres copywriter de Eagles Digital Solutions y Eagles Gear Solutions.

Escribe copys breves, claros, directos y listos para publicar en español de México. La audiencia principal son técnicos, transmisionistas y dueños de taller. Usa emojis con moderación y un llamado a la acción sencillo.

REGLAS OBLIGATORIAS:
- Usa únicamente los datos recibidos y las reglas específicas de campaña incluidas abajo.
- Nunca inventes precios, fechas, horarios, lugares, promociones, garantías, enlaces ni disponibilidad.
- Si un dato no viene y tampoco está confirmado en las reglas de campaña, omítelo.
- No prometas resultados económicos.
- En servicios de taller no des un diagnóstico definitivo por mensaje.
- Si hay varios canales, entrega una sola versión que funcione bien en los canales solicitados, salvo que se pida explícitamente otra cosa.
- Para WhatsApp usa tono cercano; “carnalitos” puede usarse cuando sea un calentamiento para grupo.
- Mantén párrafos cortos y separaciones visuales.
- Respeta los enlaces y números literalmente.
- No expliques tu proceso.
- Devuelve únicamente JSON válido.${structureRules}

FORMATO:
{"copy":"texto listo para publicar","image_prompt":"prompt visual o cadena vacía"}`;

const userPrompt = `Crea un copy con estos datos:
Categoría: ${categoryLabels[request.category] || clean(request.category) || 'redes sociales'}
Campaña: ${clean(request.campaign_code || body.campaign_code)}
Tema: ${clean(request.product_topic)}
Objetivo: ${clean(request.objective) || 'Venta'}
Canales: ${channels.join(', ')}
Tono: ${clean(request.tone) || 'Directo y profesional'}
Requiere imagen: ${request.needs_image === true ? 'sí' : 'no'}
Datos confirmados:
${facts || 'No hay datos adicionales; trabaja solamente con el tema y las reglas confirmadas de campaña.'}`;

return [{
  json: {
    request_id: clean(body.request_id),
    campaign_detected: isWorkshopConvencionales
      ? 'WORKSHOP_OCTUBRE'
      : isJF017
        ? 'CURSO_JF017_OCTUBRE'
        : 'GENERAL',
    ollama_request: {
      model: 'qwen2.5:3b',
      stream: false,
      keep_alive: '30m',
      format: {
        type: 'object',
        properties: {
          copy: { type: 'string' },
          image_prompt: { type: 'string' }
        },
        required: ['copy', 'image_prompt']
      },
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ],
      options: {
        temperature: 0.35,
        num_predict: 650,
        num_ctx: 4096
      }
    }
  }
}];

let content = String($json?.message?.content ?? $json?.response ?? '').trim();
content = content.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();

let parsed = null;
try {
  parsed = JSON.parse(content);
} catch {
  const start = content.indexOf('{');
  const end = content.lastIndexOf('}');
  if (start !== -1 && end > start) {
    try { parsed = JSON.parse(content.slice(start, end + 1)); } catch { parsed = null; }
  }
}

const copy = String(parsed?.copy || content || '').trim();
if (!copy) throw new Error('Ollama no devolvió un copy');

return [{
  json: {
    copy,
    image_prompt: String(parsed?.image_prompt || '').trim(),
    execution_id: String($execution.id)
  }
}];
